      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('es_pagos')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('es_reservas')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('es_departamentos')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('es_catalogos')}?ecosistema=${eco}`)
    ]);

    if (resPagos.ok) setPagos(resPagos.registros.sort((a, b) => new Date(b.fecha_pago) - new Date(a.fecha_pago)));
    if (resRes.ok) setReservas(resRes.registros);
    if (resDep.ok) setDeptos(resDep.registros);
    if (resCat.ok) setCatalogos(resCat.registros.sort((a, b) => Number(a.orden) - Number(b.orden)));

    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  if (!esAdmin) return <UI.EstadoVacio icono="fa-lock" mensaje={MEITI.t('admin_only', null, 'Acceso restringido a administración.')} />;

  const metodosPago = catalogos.filter(c => c.tipo === 'metodo_pago').map(c => ({ value: c.valor, label: c.valor }));
  const estadosPago = catalogos.filter(c => c.tipo === 'estado_pago').map(c => ({ value: c.valor, label: c.valor }));

  const guardar = async (e) => {
    e.preventDefault();
    setError(null);
    setExito(null);

    if (!form.reserva_id || !form.monto || !form.metodo_pago || !form.estado) {
      return setError(MEITI.t('all_fields_req', null, 'Todos los campos son obligatorios.'));
    }

    const existente = pagos.find(p => p.id === form.id);
    const payload = {
      id: form.id || 'pago_' + Date.now(),
      reserva_id: form.reserva_id,
      registrado_por: MEITI.obtenerUsuarioActual(),
      monto: Number(form.monto),
      metodo_pago: form.metodo_pago,
      estado: form.estado,
      fecha_pago: existente ? existente.fecha_pago : new Date().toISOString()
    };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('es_pagos')}?ecosistema=${eco}`, {
      method: form.id ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('payment_saved', null, 'Pago registrado correctamente.'));
        setForm({ id: '', reserva_id: '', monto: '', metodo_pago: '', estado: '' });
        cargar();
      },
      alFallar: setError
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('delete_payment_q', null, '¿Eliminar este pago?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('delete_yes', null, 'Sí, borrar'), tono: 'peligro' })) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('es_pagos')}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, {
      alLograr: cargar,
      alFallar: setError
    });
  };

  const editar = (f) => {
    setForm({ id: f.id, reserva_id: f.reserva_id, monto: f.monto, metodo_pago: f.metodo_pago, estado: f.estado });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const columnas = [
    { clave: 'reserva_id', etiqueta: MEITI.t('reservation', null, 'Reserva'), render: f => {
      const r = reservas.find(x => x.id === f.reserva_id);
      const d = deptos.find(x => x.id === r?.departamento_id);
      return r ? `${r.nombre_huesped} (${d?.nombre || MEITI.t('unknown_depto', null, 'Desconocido')})` : '---';
    }},
    { clave: 'monto', etiqueta: MEITI.t('amount', null, 'Monto'), tipo: 'moneda' },
    { clave: 'metodo_pago', etiqueta: MEITI.t('method', null, 'Método') },
    { clave: 'fecha_pago', etiqueta: MEITI.t('date', null, 'Fecha'), tipo: 'fecha' },
    { clave: 'estado', etiqueta: MEITI.t('status', null, 'Estado'), render: f => <UI.Chip tono={f.estado === 'Completado' ? 'exito' : 'alerta'}>{f.estado}</UI.Chip> }
  ];

  const saldos = reservas.filter(r => r.estado !== 'Cancelada').map(r => {
    const pagosReserva = pagos.filter(p => p.reserva_id === r.id && p.estado === 'Completado');
    const totalPagado = pagosReserva.reduce((acc, p) => acc + Number(p.monto), 0);
    const pendiente = Number(r.monto_total) - totalPagado;
    return { ...r, totalPagado, pendiente };
  }).filter(r => r.pendiente > 0);

  return (
    <div className="flex flex-col gap-8">
      <h2 className="font-serif text-3xl tracking-tight" style={{ color: tema.texto }}>{MEITI.t('payment_control', null, 'Control de Pagos')}</h2>
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="md:col-span-1 flex flex-col gap-8">
          <UI.Tarjeta className="p-6 rounded-3xl">
            <h3 className="font-bold mb-4" style={{ color: tema.texto }}>{form.id ? MEITI.t('edit_payment', null, 'Editar Pago') : MEITI.t('register_payment', null, 'Registrar Pago Manual')}</h3>
            <form onSubmit={guardar} className="flex flex-col gap-4">
              <UI.Campo 
                etiqueta={MEITI.t('reservation', null, 'Reserva')} 
                tipo="select" 
                valor={form.reserva_id} 
                onChange={e => setForm({ ...form, reserva_id: e.target.value })} 
                opciones={[{ value: '', label: MEITI.t('select_ph', null, 'Seleccionar...') }, ...reservas.filter(r => r.estado !== 'Cancelada').map(r => ({ value: r.id, label: `${r.nombre_huesped} - $${r.monto_total}` }))]} 
              />
              <UI.Campo 
                etiqueta={MEITI.t('amount', null, 'Monto')} 
                tipo="number" 
                valor={form.monto} 
                onChange={e => setForm({ ...form, monto: e.target.value })} 
              />
              <UI.Campo 
                etiqueta={MEITI.t('method', null, 'Método')} 
                tipo="select" 
                valor={form.metodo_pago} 
                onChange={e => setForm({ ...form, metodo_pago: e.target.value })} 
                opciones={[{ value: '', label: MEITI.t('select_ph', null, 'Seleccionar...') }, ...metodosPago]} 
              />
              <UI.Campo 
                etiqueta={MEITI.t('status', null, 'Estado')} 
                tipo="select" 
                valor={form.estado} 
                onChange={e => setForm({ ...form, estado: e.target.value })} 
                opciones={[{ value: '', label: MEITI.t('select_ph', null, 'Seleccionar...') }, ...estadosPago]} 
              />
              <div className="flex gap-2 mt-2">
                <UI.Boton tipo="submit" variante="primario">{form.id ? MEITI.t('update', null, 'Actualizar') : MEITI.t('register', null, 'Registrar')}</UI.Boton>
                {form.id && <UI.Boton tipo="button" variante="secundario" onClick={() => setForm({ id: '', reserva_id: '', monto: '', metodo_pago: '', estado: '' })}>{MEITI.t('cancel', null, 'Cancelar')}</UI.Boton>}
              </div>
            </form>
          </UI.Tarjeta>

          <UI.Tarjeta className="p-6 rounded-3xl">
            <h3 className="font-bold mb-4" style={{ color: tema.texto }}>{MEITI.t('pending_balances', null, 'Saldos Pendientes')}</h3>
            {saldos.length === 0 ? (
              <p className="text-sm opacity-70" style={{ color: tema.texto }}>{MEITI.t('no_pending_balances', null, 'No hay saldos pendientes.')}</p>
            ) : (
              <div className="flex flex-col gap-3">
                {saldos.map(s => (
                  <div key={s.id} className="flex justify-between items-center p-3 rounded-xl border" style={{ borderColor: tema.texto + '1A', backgroundColor: tema.fondo }}>
                    <div className="flex flex-col">
                      <span className="font-bold text-sm" style={{ color: tema.texto }}>{s.nombre_huesped}</span>
                      <span className="text-xs opacity-70" style={{ color: tema.texto }}>{MEITI.t('total', null, 'Total')}: ${s.monto_total}</span>
                    </div>
                    <span className="font-bold" style={{ color: tema.colorPrimario }}>${s.pendiente}</span>
                  </div>
                ))}
              </div>
            )}
          </UI.Tarjeta>
        </div>

        <div className="md:col-span-2 flex flex-col">
          <UI.Tarjeta className="p-6 rounded-3xl flex-1 flex flex-col min-h-0">
            <h3 className="font-bold mb-4" style={{ color: tema.texto }}>{MEITI.t('payment_history', null, 'Historial de Pagos')}</h3>
            <div className="flex-1 min-h-0 flex flex-col">
              {cargando ? (
                <p style={{ color: tema.texto }}>{MEITI.t('loading', null, 'Cargando...')}</p>
              ) : pagos.length === 0 ? (
                <UI.EstadoVacio icono="fa-receipt" mensaje={MEITI.t('no_payments', null, 'No hay pagos registrados.')} />
              ) : (
                <UI.TablaDatos columnas={columnas} datos={pagos} claveId="id" onEditar={editar} onBorrar={f => borrar(f.id)} />
              )}
            </div>
          </UI.Tarjeta>
        </div>
      </div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const tLimpieza = MEITI.obtenerTabla('es_limpieza');
  const tDeptos = MEITI.obtenerTabla('es_departamentos');

  const [tareas, setTareas] = useState([]);
  const [departamentos, setDepartamentos] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const vacio = { id: '', departamento_id: '', asignado_a: '', estado: 'pendiente', fecha_programada: '', notas: '' };
  const [form, setForm] = useState(vacio);

  const cargar = async () => {
    setCargando(true);
    const [resLimpieza, resDeptos] = await Promise.all([
      MEITI.fetchDatos(`/api/boveda/${tLimpieza}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${tDeptos}?ecosistema=${eco}`)
    ]);
    if (resLimpieza.ok) setTareas(resLimpieza.registros || []);
    if (resDeptos.ok) setDepartamentos(resDeptos.registros || []);
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
    e.preventDefault();
    setError(null);
    setExito(null);

    if (!form.departamento_id) {
      return setError(MEITI.t('err_depto_req', null, 'Selecciona un departamento para la tarea.'));
    }

    setGuardando(true);
    const esNuevo = !form.id;
    const payload = {
      id: esNuevo ? 'limp_' + Date.now() : form.id,
      departamento_id: form.departamento_id,
      asignado_a: form.asignado_a,
      estado: form.estado,
      fecha_programada: form.fecha_programada,
      notas: form.notas
    };

    await MEITI.mutar(`/api/boveda/${tLimpieza}?ecosistema=${eco}`, {
      method: esNuevo ? 'POST' : 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(esNuevo ? MEITI.t('msg_task_created', null, 'Tarea programada con éxito.') : MEITI.t('msg_task_updated', null, 'Tarea actualizada.'));
        setForm(vacio);
        cargar();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_saving_task', null, 'No se pudo guardar la tarea.'));
        setGuardando(false);
      }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('q_delete_task', null, '¿Borrar esta tarea de limpieza?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;
    setError(null);
    setExito(null);

    await MEITI.mutar(`/api/boveda/${tLimpieza}?ecosistema=${eco}&id=${id}`, {
      method: 'DELETE'
    }, {
      alLograr: () => {
        setExito(MEITI.t('msg_task_deleted', null, 'Tarea eliminada.'));
        if (form.id === id) setForm(vacio);
        cargar();
      },
      alFallar: (err) => setError(err || MEITI.t('err_deleting_task', null, 'No se pudo eliminar la tarea.'))
    });
  };

  const editar = (fila) => {
    setForm({
      id: fila.id,
      departamento_id: fila.departamento_id || '',
      asignado_a: fila.asignado_a || '',
      estado: fila.estado || 'pendiente',
      fecha_programada: fila.fecha_programada || '',
      notas: fila.notas || ''
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const marcarListo = async (fila) => {
    await MEITI.mutar(`/api/boveda/${tLimpieza}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...fila, estado: 'listo' })
    }, {
      alLograr: () => cargar(),
      alFallar: (err) => setError(err || MEITI.t('err_updating_status', null, 'Error al actualizar el estado.'))
    });
  };

  const columnas = [
    { clave: 'departamento_id', etiqueta: MEITI.t('col_depto', null, 'Departamento'), render: (f) => departamentos.find(d => d.id === f.departamento_id)?.nombre || '---' },
    { clave: 'fecha_programada', etiqueta: MEITI.t('col_date', null, 'Fecha Programada'), tipo: 'fecha' },
    { clave: 'asignado_a', etiqueta: MEITI.t('col_assigned', null, 'Asignado a') },
    { clave: 'estado', etiqueta: MEITI.t('col_status', null, 'Estado'), render: (f) => <UI.Chip tono={f.estado === 'listo' ? 'exito' : 'alerta'}>{f.estado === 'listo' ? MEITI.t('st_ready', null, 'Listo') : MEITI.t('st_pending', null, 'Pendiente')}</UI.Chip> }
  ];

  const accionesExtra = [
    {
      etiqueta: MEITI.t('act_mark_ready', null, 'Marcar Listo'),
      icono: 'fa-check',
      tono: 'exito',
      condicion: (f) => f.estado !== 'listo',
      onClick: marcarListo
    }
  ];

  const pendientes = tareas.filter(t => t.estado !== 'listo').length;
  const listas = tareas.filter(t => t.estado === 'listo').length;

  return (
    <div className="flex flex-col gap-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-4">
            <div className="w-12 h-12 rounded-full flex items-center justify-center" style={{ backgroundColor: tema.colorPrimario + '22', color: tema.colorPrimario }}>
              <Iconos.Sparkles size={24} />
            </div>
            <div>
              <p className="text-sm font-bold opacity-70 uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('kpi_total', null, 'Total Tareas')}</p>
              <p className="text-2xl font-black" style={{ color: tema.texto }}>{tareas.length}</p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-4">
            <div className="w-12 h-12 rounded-full flex items-center justify-center" style={{ backgroundColor: '#f59e0b22', color: '#f59e0b' }}>
              <Iconos.Clock size={24} />
            </div>
            <div>
              <p className="text-sm font-bold opacity-70 uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('kpi_pending', null, 'Pendientes')}</p>
              <p className="text-2xl font-black" style={{ color: tema.texto }}>{pendientes}</p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.2 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-4">
            <div className="w-12 h-12 rounded-full flex items-center justify-center" style={{ backgroundColor: '#10b98122', color: '#10b981' }}>
              <Iconos.CircleCheck size={24} />
            </div>
            <div>
              <p className="text-sm font-bold opacity-70 uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('kpi_ready', null, 'Completadas')}</p>
              <p className="text-2xl font-black" style={{ color: tema.texto }}>{listas}</p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
      </div>

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.3 }}>
        <UI.Tarjeta>
          <div className="flex items-center gap-2 mb-4">
            <Iconos.Sparkles size={20} color={tema.colorPrimario} />
            <UI.Etiqueta>{form.id ? MEITI.t('title_edit_task', null, 'Editar Tarea de Limpieza') : MEITI.t('title_new_task', null, 'Programar Limpieza')}</UI.Etiqueta>
          </div>

          <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
          <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

          <form onSubmit={guardar} className="flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="flex-1">
                <UI.Campo 
                  etiqueta={MEITI.t('f_depto', null, 'Departamento')} 
                  tipo="select" 
                  valor={form.departamento_id} 
                  onChange={e => setForm({...form, departamento_id: e.target.value})} 
                  opciones={[{value: '', label: MEITI.t('ph_select_depto', null, 'Seleccionar...')}, ...departamentos.map(d => ({ value: d.id, label: d.nombre }))]}
                />
              </div>
              <div className="flex-1">
                <UI.Campo 
                  etiqueta={MEITI.t('f_date', null, 'Fecha Programada')} 
                  tipo="date" 
                  valor={form.fecha_programada} 
                  onChange={e => setForm({...form, fecha_programada: e.target.value})} 
                />
              </div>
              <div className="flex-1">
                <UI.Campo 
                  etiqueta={MEITI.t('f_assigned', null, 'Asignado a (Nombre)')} 
                  tipo="text" 
                  valor={form.asignado_a} 
                  onChange={e => setForm({...form, asignado_a: e.target.value})} 
                  placeholder={MEITI.t('ph_assigned', null, 'Ej: María Gómez')}
                />
              </div>
              <div className="flex-1">
                <UI.Campo 
                  etiqueta={MEITI.t('f_status', null, 'Estado')} 
                  tipo="select" 
                  valor={form.estado} 
                  onChange={e => setForm({...form, estado: e.target.value})} 
                  opciones={[{value: 'pendiente', label: MEITI.t('st_pending', null, 'Pendiente')}, {value: 'listo', label: MEITI.t('st_ready', null, 'Listo')}]}
                />
              </div>
              <div className="md:col-span-2 flex-1">
                <UI.Campo 
                  etiqueta={MEITI.t('f_notes', null, 'Notas o Instrucciones Especiales')} 
                  tipo="textarea" 
                  valor={form.notas} 
                  onChange={e => setForm({...form, notas: e.target.value})} 
                  placeholder={MEITI.t('ph_notes', null, 'Ej: Reponer toallas extra, revisar aire acondicionado...')}
                />
              </div>
            </div>
            <div className="flex gap-2 mt-2">
              <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
                <span className="flex items-center gap-2">
                  <Iconos.Save size={16} /> 
                  {guardando ? MEITI.t('btn_saving', null, 'Guardando...') : (form.id ? MEITI.t('btn_update', null, 'Actualizar Tarea') : MEITI.t('btn_create', null, 'Programar Tarea'))}
                </span>
              </UI.Boton>
              {form.id && (
                <UI.Boton tipo="button" variante="secundario" onClick={() => setForm(vacio)}>
                  <span className="flex items-center gap-2">
                    <Iconos.X size={16} /> 
                    {MEITI.t('btn_cancel', null, 'Cancelar')}
                  </span>
                </UI.Boton>
              )}
            </div>
          </form>
        </UI.Tarjeta>
      </Animacion.motion.div>

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.4 }}>
        <UI.Tarjeta className="flex flex-col gap-4">
          <UI.Etiqueta>{MEITI.t('title_task_list', null, 'Planilla de Limpieza')}</UI.Etiqueta>
          {cargando ? (
            <p style={{color: tema.texto}}>{MEITI.t('loading_tasks', null, 'Cargando tareas...')}</p>
          ) : tareas.length === 0 ? (
            <UI.EstadoVacio icono="fa-broom" mensaje={MEITI.t('empty_tasks', null, 'No hay tareas de limpieza programadas.')} />
          ) : (
            <UI.TablaDatos 
              columnas={columnas} 
              datos={tareas} 
              claveId="id" 
              onEditar={editar} 
              onBorrar={(fila) => borrar(fila.id)} 
              accionesExtra={accionesExtra}
            />
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const esAdmin = MEITI.miRolEnLaApp() === 'admin' || MEITI.soyDuenoDeLaApp();
  if (!esAdmin) return <UI.Aviso tono="peligro" mensaje={MEITI.t('admin_only', null, 'Acceso restringido: esta sección es solo para administradores.')} />;

  const eco = MEITI.obtenerEcosistemaActual();
  const tabla = MEITI.obtenerTabla('es_catalogos');

  const [datosCat, setDatosCat] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const tiposCatalogo = [
    { id: 'estado_reserva', etiqueta: MEITI.t('cat_reserva', null, 'Estados de Reserva'), icono: <Iconos.CalendarClock size={18} /> },
    { id: 'metodo_pago', etiqueta: MEITI.t('cat_pago', null, 'Métodos de Pago'), icono: <Iconos.CreditCard size={18} /> },
    { id: 'servicio_depto', etiqueta: MEITI.t('cat_servicio', null, 'Servicios de Depto'), icono: <Iconos.Wifi size={18} /> }
  ];

  const [tipoActivo, setTipoActivo] = useState(tiposCatalogo[0].id);
  const vacio = { id: '', valor: '', orden: 0 };
  const [form, setForm] = useState(vacio);

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatos(`/api/boveda/${tabla}?ecosistema=${eco}`);
    if (res.ok) {
      setDatosCat(res.registros || []);
    } else {
      setError(res.error || MEITI.t('err_load_cat', null, 'Error al cargar los catálogos.'));
    }
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
    e.preventDefault();
    setError(null);
    setExito(null);

    if (!form.valor.trim()) {
      return setError(MEITI.t('err_val_req', null, 'El valor de la opción es obligatorio.'));
    }

    setGuardando(true);
    const esNuevo = !form.id;
    const payload = {
      id: esNuevo ? 'cat_' + Date.now() : form.id,
      tipo: tipoActivo,
      valor: form.valor.trim(),
      orden: Number(form.orden) || 0
    };

    await MEITI.mutar(`/api/boveda/${tabla}?ecosistema=${eco}`, {
      method: esNuevo ? 'POST' : 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(esNuevo ? MEITI.t('msg_cat_created', null, 'Opción agregada con éxito.') : MEITI.t('msg_cat_updated', null, 'Opción actualizada.'));
        setForm(vacio);
        cargar();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_save_cat', null, 'No se pudo guardar la opción.'));
        setGuardando(false);
      }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('q_delete_cat', null, '¿Borrar esta opción del catálogo?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;
    setError(null);
    setExito(null);

    await MEITI.mutar(`/api/boveda/${tabla}?ecosistema=${eco}&id=${id}`, {
      method: 'DELETE'
    }, {
      alLograr: () => {
        setExito(MEITI.t('msg_cat_deleted', null, 'Opción eliminada.'));
        if (form.id === id) setForm(vacio);
        cargar();
      },
      alFallar: (err) => setError(err || MEITI.t('err_delete_cat', null, 'No se pudo eliminar la opción.'))
    });
  };

  const editar = (fila) => {
    setForm({
      id: fila.id,
      valor: fila.valor || '',
      orden: fila.orden || 0
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cambiarPestana = (id) => {
    setTipoActivo(id);
    setForm(vacio);
    setError(null);
    setExito(null);
  };

  const filtrados = datosCat.filter(d => d.tipo === tipoActivo).sort((a, b) => (a.orden || 0) - (b.orden || 0));

  const columnas = [
    { clave: 'orden', etiqueta: MEITI.t('col_order', null, 'Orden'), tipo: 'numero' },
    { clave: 'valor', etiqueta: MEITI.t('col_value', null, 'Valor / Opción') }
  ];

  return (
    <div className="flex flex-col gap-6">
      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
        <div className="flex gap-3 overflow-x-auto pb-2">
          {tiposCatalogo.map(t => (
            <button
              key={t.id}
              onClick={() => cambiarPestana(t.id)}
              className="flex items-center gap-2 px-5 py-3 rounded-xl font-bold transition-all whitespace-nowrap"
              style={{
                background: tipoActivo === t.id ? tema.colorPrimario : tema.superficie,
                color: tipoActivo === t.id ? '#fff' : tema.texto,
                border: `1px solid ${tipoActivo === t.id ? tema.colorPrimario : tema.texto + '22'}`
              }}
            >
              {t.icono}
              {t.etiqueta}
            </button>
          ))}
        </div>
      </Animacion.motion.div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1">
          <Animacion.motion.div initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.3, delay: 0.1 }}>
            <UI.Tarjeta>
              <div className="flex items-center gap-2 mb-4">
                <Iconos.Settings2 size={20} color={tema.colorPrimario} />
                <UI.Etiqueta>{form.id ? MEITI.t('title_edit_opt', null, 'Editar Opción') : MEITI.t('title_new_opt', null, 'Nueva Opción')}</UI.Etiqueta>
              </div>

              <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
              <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

              <form onSubmit={guardar} className="flex flex-col gap-4">
                <div className="flex flex-col gap-4">
                  <div className="flex-1">
                    <UI.Campo 
                      etiqueta={MEITI.t('f_value', null, 'Valor de la opción')} 
                      tipo="text" 
                      valor={form.valor} 
                      onChange={e => setForm({...form, valor: e.target.value})} 
                      placeholder={MEITI.t('ph_value', null, 'Ej: Confirmada, Tarjeta, WiFi...')}
                    />
                  </div>
                  <div className="flex-1">
                    <UI.Campo 
                      etiqueta={MEITI.t('f_order', null, 'Orden (para listados)')} 
                      tipo="number" 
                      valor={form.orden} 
                      onChange={e => setForm({...form, orden: e.target.value})} 
                    />
                  </div>
                </div>
                <div className="flex flex-col gap-2 mt-2">
                  <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
                    <span className="flex items-center justify-center gap-2">
                      <Iconos.Save size={16} /> 
                      {guardando ? MEITI.t('btn_saving', null, 'Guardando...') : (form.id ? MEITI.t('btn_update', null, 'Actualizar Opción') : MEITI.t('btn_create', null, 'Agregar Opción'))}
                    </span>
                  </UI.Boton>
                  {form.id && (
                    <UI.Boton tipo="button" variante="secundario" onClick={() => setForm(vacio)}>
                      <span className="flex items-center justify-center gap-2">
                        <Iconos.X size={16} /> 
                        {MEITI.t('btn_cancel', null, 'Cancelar')}
                      </span>
                    </UI.Boton>
                  )}
                </div>
              </form>
            </UI.Tarjeta>
          </Animacion.motion.div>
        </div>

        <div className="lg:col-span-2 flex flex-col">
          <Animacion.motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.3, delay: 0.2 }} className="flex-1 flex flex-col min-h-0">
            <UI.Tarjeta className="flex-1 flex flex-col">
              <div className="flex items-center gap-2 mb-4">
                <Iconos.List size={20} color={tema.colorSecundario} />
                <UI.Etiqueta>{MEITI.t('title_cat_list', null, 'Opciones Registradas')}</UI.Etiqueta>
              </div>

              <div className="flex-1 min-h-0 overflow-y-auto">
                {cargando ? (
                  <div className="p-8 text-center">
                    <Iconos.LoaderCircle size={32} className="animate-spin mx-auto mb-2" color={tema.colorPrimario} />
                    <p style={{color: tema.texto}}>{MEITI.t('loading_cat', null, 'Cargando opciones...')}</p>
                  </div>
                ) : filtrados.length === 0 ? (
                  <UI.EstadoVacio icono="fa-tags" mensaje={MEITI.t('empty_cat', null, 'No hay opciones registradas en este catálogo.')} />
                ) : (
                  <UI.TablaDatos 
                    columnas={columnas} 
                    datos={filtrados} 
                    claveId="id" 
                    onEditar={editar} 
                    onBorrar={(fila) => borrar(fila.id)} 
                  />
                )}
              </div>
            </UI.Tarjeta>
          </Animacion.motion.div>
        </div>
      </div>
    </div>
  );
}
